平衡二叉树 (AVL Tree) 从零实现
仅依赖 Python 标准库 (random)

原理:
  AVL 树是一种自平衡二叉搜索树，保证任意节点的左右子树高度差 ≤ 1。
  通过四种旋转操作 (LL, RR, LR, RL) 在插入/删除后恢复平衡。

核心数据结构:
  AVLNode —— 节点类 (key, left, right, height)
  AVLTree —— 树类 (root, size) + 插入/删除/查找/遍历

时间复杂度:
  插入/删除/查找 O(log n)   遍历 O(n)   空间 O(n)
"""

import random


# ══════════════════════════════════════════════════════════════
#  AVL 节点
# ══════════════════════════════════════════════════════════════

class AVLNode:
    """AVL 树节点"""

    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.height = 1  # 叶子节点高度为 1

    def __repr__(self):
        return f"AVLNode({self.key})"


# ══════════════════════════════════════════════════════════════
#  AVL 树
# ══════════════════════════════════════════════════════════════

class AVLTree:
    """
    AVL 平衡二叉搜索树

    用法:
      tree = AVLTree()
      tree.insert(50)
      tree.insert(30)
      tree.insert(70)
      print(tree.inorder())        # [30, 50, 70]
      tree.delete(50)
      print(tree.search(50))       # None
    """

    def __init__(self):
        self.root = None
        self._size = 0

    @property
    def size(self):
        return self._size

    # ── 辅助方法 ──

    @staticmethod
    def _height(node):
        """返回节点高度 (None 高度为 0)"""
        return node.height if node else 0

    def _update_height(self, node):
        """重新计算节点高度"""
        node.height = 1 + max(self._height(node.left), self._height(node.right))

    def _balance_factor(self, node):
        """平衡因子 = 左高 - 右高"""
        return self._height(node.left) - self._height(node.right)

    # ── 旋转操作 ──

    def _rotate_right(self, y):
        """右旋 (处理 LL 失衡)"""
        x = y.left
        T = x.right
        x.right = y
        y.left = T
        self._update_height(y)
        self._update_height(x)
        return x

    def _rotate_left(self, x):
        """左旋 (处理 RR 失衡)"""
        y = x.right
        T = y.left
        y.left = x
        x.right = T
        self._update_height(x)
        self._update_height(y)
        return y

    def _rebalance(self, node):
        """根据平衡因子自动选择旋转策略并重新平衡"""
        self._update_height(node)
        bf = self._balance_factor(node)

        # 左子树过高
        if bf > 1:
            if self._balance_factor(node.left) < 0:
                # LR: 先左旋左子树
                node.left = self._rotate_left(node.left)
            # LL: 右旋当前节点
            return self._rotate_right(node)

        # 右子树过高
        if bf < -1:
            if self._balance_factor(node.right) > 0:
                # RL: 先右旋右子树
                node.right = self._rotate_right(node.right)
            # RR: 左旋当前节点
            return self._rotate_left(node)

        return node

    # ── 插入 ──

    def insert(self, key):
        """插入键值，自动保持平衡。重复键忽略。"""
        if self.search(key) is not None:
            return False
        self.root = self._insert(self.root, key)
        self._size += 1
        return True

    def _insert(self, node, key):
        if not node:
            return AVLNode(key)
        if key < node.key:
            node.left = self._insert(node.left, key)
        elif key > node.key:
            node.right = self._insert(node.right, key)
        return self._rebalance(node)

    # ── 删除 ──

    def delete(self, key):
        """删除指定键值，自动保持平衡。"""
        if self.search(key) is None:
            return False
        self.root = self._delete(self.root, key)
        self._size -= 1
        return True

    def _delete(self, node, key):
        if not node:
            return node
        if key < node.key:
            node.left = self._delete(node.left, key)
        elif key > node.key:
            node.right = self._delete(node.right, key)
        else:
            # 找到要删除的节点
            if not node.left:
                return node.right
            if not node.right:
                return node.left
            # 有两个子节点: 用右子树最小值替换
            min_node = self._min_node(node.right)
            node.key = min_node.key
            node.right = self._delete(node.right, min_node.key)
        return self._rebalance(node)

    # ── 查找 ──

    def search(self, key):
        """查找键值，返回节点或 None"""
        node = self.root
        while node:
            if key == node.key:
                return node
            elif key < node.key:
                node = node.left
            else:
                node = node.right
        return None

    def contains(self, key):
        """判断键值是否存在"""
        return self.search(key) is not None

    # ── 最值 ──

    def _min_node(self, node):
        """返回子树中最小节点"""
        while node.left:
            node = node.left
        return node

    def _max_node(self, node):
        """返回子树中最大节点"""
        while node.right:
            node = node.right
        return node

    def min_key(self):
        """最小键值"""
        return self._min_node(self.root).key if self.root else None

    def max_key(self):
        """最大键值"""
        return self._max_node(self.root).key if self.root else None

    # ── 遍历 ──

    def inorder(self):
        """中序遍历 (升序)"""
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, result):
        if node:
            self._inorder(node.left, result)
            result.append(node.key)
            self._inorder(node.right, result)

    def preorder(self):
        """前序遍历"""
        result = []
        self._preorder(self.root, result)
        return result

    def _preorder(self, node, result):
        if node:
            result.append(node.key)
            self._preorder(node.left, result)
            self._preorder(node.right, result)

    def postorder(self):
        """后序遍历"""
        result = []
        self._postorder(self.root, result)
        return result

    def _postorder(self, node, result):
        if node:
            self._postorder(node.left, result)
            self._postorder(node.right, result)
            result.append(node.key)

    # ── 树高 ──

    def height(self):
        """树高"""
        return self._height(self.root)

    # ── 验证 AVL 性质 ──

    def is_valid(self):
        """验证是否为合法 AVL 树"""
        return self._is_valid(self.root, float('-inf'), float('inf'))

    def _is_valid(self, node, min_val, max_val):
        if not node:
            return True
        if node.key <= min_val or node.key >= max_val:
            return False
        if abs(self._balance_factor(node)) > 1:
            return False
        return (self._is_valid(node.left, min_val, node.key) and
                self._is_valid(node.right, node.key, max_val))

    # ── 优雅打印 ──

    def print_tree(self):
        """可视化打印 AVL 树结构"""
        if not self.root:
            print("  (empty tree)")
            return
        lines = []
        self._build_lines(self.root, "", True, lines)
        print("\n".join(lines))

    def _build_lines(self, node, prefix, is_last, lines):
        if node is None:
            return
        lines.append(prefix + ("└── " if is_last else "├── ") + f"{node.key} (h={node.height})")
        new_prefix = prefix + ("    " if is_last else "│   ")
        children = []
        if node.left:
            children.append(('L', node.left))
        if node.right:
            children.append(('R', node.right))
        for i, (label, child) in enumerate(children):
            is_last_child = (i == len(children) - 1)
            self._build_lines(child, new_prefix, is_last_child, lines)

    def __len__(self):
        return self._size

    def __contains__(self, key):
        return self.contains(key)

    def __repr__(self):
        return f"AVLTree(size={self._size}, height={self.height()})"
"}

