 * lru_cache.c — LRU Cache C 语言实现
 * 哈希表 (开放地址法) + 双向链表
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "lru_cache.h"

/* ══════════════════════════════════════════════════════════════
 *  内部常量与辅助
 * ══════════════════════════════════════════════════════════════ */

#define HASH_LOAD_FACTOR  0.6
#define HASH_MIN_SIZE     17

/* 空桶标记 */
static const int EMPTY_KEY = -1;  /* key=-1 表示空桶 */

/* 查找大于等于 n 的最小素数 (用于哈希表大小) */
static int _next_prime(int n) {
    if (n < 2) return 2;
    if (n % 2 == 0) n++;
    while (1) {
        int prime = 1;
        for (int d = 3; (long long)d * d <= n; d += 2) {
            if (n % d == 0) { prime = 0; break; }
        }
        if (prime) return n;
        n += 2;
    }
}

/* 哈希函数 */
static int _hash(int key, int table_size) {
    int h = key % table_size;
    return h < 0 ? h + table_size : h;
}

/* ══════════════════════════════════════════════════════════════
 *  链表内部操作
 * ══════════════════════════════════════════════════════════════ */

/* 从链表中摘除节点 */
static void _list_remove(LRU_Node *node) {
    node->prev->next = node->next;
    node->next->prev = node->prev;
}

/* 在 head 之后插入 (最前端) */
static void _list_add_head(LRUCache *cache, LRU_Node *node) {
    node->prev = cache->head;
    node->next = cache->head->next;
    cache->head->next->prev = node;
    cache->head->next = node;
}

/* 移动到最前端 */
static void _list_move_to_head(LRUCache *cache, LRU_Node *node) {
    _list_remove(node);
    _list_add_head(cache, node);
}

/* 移除并返回尾部节点 */
static LRU_Node *_list_pop_tail(LRUCache *cache) {
    LRU_Node *node = cache->tail->prev;
    _list_remove(node);
    return node;
}

/* ══════════════════════════════════════════════════════════════
 *  哈希表操作 (开放地址法, 线性探测)
 * ══════════════════════════════════════════════════════════════ */

/* 在哈希表中查找 key, 返回桶下标 */
static int _hash_find(LRUCache *cache, int key) {
    int idx = _hash(key, cache->hash_size);
    for (int i = 0; i < cache->hash_size; i++) {
        int probe = (idx + i) % cache->hash_size;
        LRU_Node *node = cache->hash_table[probe];
        if (node == NULL) return -1;           /* 空桶, 不存在 */
        if (node->key == key) return probe;    /* 找到 */
    }
    return -1;
}

/* 在哈希表中插入节点 */
static void _hash_insert(LRUCache *cache, LRU_Node *node) {
    int idx = _hash(node->key, cache->hash_size);
    for (int i = 0; i < cache->hash_size; i++) {
        int probe = (idx + i) % cache->hash_size;
        if (cache->hash_table[probe] == NULL) {
            cache->hash_table[probe] = node;
            return;
        }
    }
}

/* 从哈希表中删除指定桶位置的节点 */
static void _hash_delete_at(LRUCache *cache, int idx) {
    cache->hash_table[idx] = NULL;
    /* 线性探测需要重新哈希后续连续元素 */
    int table_size = cache->hash_size;
    int gap = idx;
    for (int i = 1; i < table_size; i++) {
        int next = (idx + i) % table_size;
        LRU_Node *node = cache->hash_table[next];
        if (node == NULL) break;
        int ideal = _hash(node->key, table_size);
        /* 判断是否需要搬迁 */
        int dist;
        if (ideal <= gap) {
            dist = gap - ideal;
        } else {
            dist = table_size - ideal + gap;
        }
        if (dist < i) {
            /* 需要搬迁 */
            cache->hash_table[gap] = node;
            cache->hash_table[next] = NULL;
            gap = next;
        }
    }
}

/* ══════════════════════════════════════════════════════════════
 *  公开 API 实现
 * ══════════════════════════════════════════════════════════════ */

LRUCache *lru_cache_create(int capacity) {
    if (capacity < 1) return NULL;

    LRUCache *cache = (LRUCache *)malloc(sizeof(LRUCache));
    if (!cache) return NULL;

    cache->capacity = capacity;
    cache->size = 0;
    cache->hash_size = _next_prime(capacity * 2);
    if (cache->hash_size < HASH_MIN_SIZE)
        cache->hash_size = HASH_MIN_SIZE;

    cache->hash_table = (LRUCache **)calloc(cache->hash_size, sizeof(LRU_Node *));
    if (!cache->hash_table) { free(cache); return NULL; }

    /* 哨兵节点 */
    cache->head = (LRU_Node *)calloc(1, sizeof(LRU_Node));
    cache->tail = (LRU_Node *)calloc(1, sizeof(LRU_Node));
    if (!cache->head || !cache->tail) {
        free(cache->hash_table); free(cache->head); free(cache->tail); free(cache);
        return NULL;
    }
    cache->head->next = cache->tail;
    cache->tail->prev = cache->head;

    return cache;
}

void lru_cache_destroy(LRUCache *cache) {
    if (!cache) return;
    /* 释放所有数据节点 */
    LRU_Node *cur = cache->head->next;
    while (cur != cache->tail) {
        LRU_Node *next = cur->next;
        free(cur);
        cur = next;
    }
    free(cache->head);
    free(cache->tail);
    free(cache->hash_table);
    free(cache);
}

int lru_cache_get(LRUCache *cache, int key) {
    if (!cache) return -1;

    int idx = _hash_find(cache, key);
    if (idx < 0) return -1;

    LRU_Node *node = cache->hash_table[idx];
    _list_move_to_head(cache, node);
    return node->value;
}

int lru_cache_put(LRUCache *cache, int key, int value) {
    if (!cache) return -1;

    /* 已存在: 更新值, 移到头部 */
    int idx = _hash_find(cache, key);
    if (idx >= 0) {
        LRU_Node *node = cache->hash_table[idx];
        node->value = value;
        _list_move_to_head(cache, node);
        return 0;
    }

    /* 不存在: 创建新节点 */
    LRU_Node *node = (LRU_Node *)malloc(sizeof(LRU_Node));
    if (!node) return -1;
    node->key = key;
    node->value = value;

    /* 容量满: 淘汰尾部 */
    if (cache->size >= cache->capacity) {
        LRU_Node *tail_node = _list_pop_tail(cache);
        int tail_idx = _hash_find(cache, tail_node->key);
        if (tail_idx >= 0) _hash_delete_at(cache, tail_idx);
        free(tail_node);
        cache->size--;
    }

    /* 插入头部和哈希表 */
    _list_add_head(cache, node);
    _hash_insert(cache, node);
    cache->size++;
    return 0;
}

int lru_cache_delete(LRUCache *cache, int key) {
    if (!cache) return 0;

    int idx = _hash_find(cache, key);
    if (idx < 0) return 0;

    LRU_Node *node = cache->hash_table[idx];
    _list_remove(node);
    _hash_delete_at(cache, idx);
    cache->size--;
    free(node);
    return 1;
}

int lru_cache_contains(LRUCache *cache, int key) {
    if (!cache) return 0;
    return _hash_find(cache, key) >= 0 ? 1 : 0;
}

int lru_cache_size(LRUCache *cache) {
    return cache ? cache->size : 0;
}

void lru_cache_clear(LRUCache *cache) {
    if (!cache) return;
    LRU_Node *cur = cache->head->next;
    while (cur != cache->tail) {
        LRU_Node *next = cur->next;
        free(cur);
        cur = next;
    }
    cache->head->next = cache->tail;
    cache->tail->prev = cache->head;
    memset(cache->hash_table, 0, sizeof(LRU_Node *) * cache->hash_size);
    cache->size = 0;
}

void lru_cache_print(LRUCache *cache) {
    if (!cache) { printf("  (NULL cache)\n"); return; }
    printf("  LRUCache(cap=%d, size=%d, list=HEAD", cache->capacity, cache->size);
    LRU_Node *cur = cache->head->next;
    while (cur != cache->tail) {
        printf(" ⇄ [%d:%d]", cur->key, cur->value);
        cur = cur->next;
    }
    printf(" ⇄ TAIL)\n");
}
